from collections import Counter

def gini(labels):
    n = len(labels)
    if n == 0:
        return 0.0
    return 1 - sum((c / n) ** 2 for c in Counter(labels).values())

def majority(labels):
    """Most common label; the smaller label on a tie, as scikit-learn."""
    c = Counter(labels)
    return min(c, key=lambda k: (-c[k], k))

def best_split(X, y):
    """(feature, threshold, gain): largest Gini gain, first found on a
    tie; (None, None, 0.0) when no split gains anything."""
    best = (None, None, 0.0)
    for f in range(len(X[0])):
        col = [row[f] for row in X]
        values = sorted(set(col))
        for a, b in zip(values, values[1:]):
            t = (a + b) / 2
            left = [lab for v, lab in zip(col, y) if v <= t]
            right = [lab for v, lab in zip(col, y) if v > t]
            g = gini(y) - (len(left) * gini(left)
                           + len(right) * gini(right)) / len(y)
            if g > best[2]:
                best = (f, t, g)
    return best

def grow(X, y, depth):
    """{"leaf": class}, or {"feature": f, "threshold": t rounded to 6,
    "left": subtree, "right": subtree}. Leaf when depth is 0, the node
    is pure, or no split gains anything."""
    if depth == 0 or len(set(y)) == 1:
        return {"leaf": majority(y)}
    f, t, g = best_split(X, y)
    if f is None:
        return {"leaf": majority(y)}
    L = [i for i, row in enumerate(X) if row[f] <= t]
    R = [i for i, row in enumerate(X) if row[f] > t]
    return {"feature": f, "threshold": round(t, 6),
            "left": grow([X[i] for i in L], [y[i] for i in L], depth - 1),
            "right": grow([X[i] for i in R], [y[i] for i in R], depth - 1)}

def predict_one(node, row):
    while "leaf" not in node:
        go_left = row[node["feature"]] <= node["threshold"]
        node = node["left"] if go_left else node["right"]
    return node["leaf"]

def build_tree_depth2(X, y, X_query):
    X = [list(r) for r in X]
    y = [int(v) for v in y]
    rules = grow(X, y, 2)
    return rules, [predict_one(rules, list(r)) for r in X_query]
